import React, { useState } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import { StatusBadge } from '../../components/common/RequestCard';
import { useAuth } from '../../context/AuthContext';
import { getRequests } from '../../utils/storage';
import { Link } from 'react-router-dom';
import './MyRequests.css';

const NAV_ITEMS = [
  { path: '/student', label: 'Dashboard', icon: '🏠', end: true },
  { path: '/student/submit', label: 'Submit Request', icon: '➕' },
  { path: '/student/requests', label: 'My Requests', icon: '📋' },
  { path: '/student/profile', label: 'Profile', icon: '👤' },
];

const STATUS_FILTERS = ['All', 'Pending', 'In Progress', 'Resolved'];
const CATEGORY_FILTERS = ['All', 'IT', 'Hostel', 'Academic', 'Administration'];

export default function MyRequests() {
  const { user } = useAuth();
  const [statusFilter, setStatusFilter] = useState('All');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [search, setSearch] = useState('');

  const allRequests = getRequests();
  const myRequests = allRequests.filter(r => r.studentId === user?.email);

  const filtered = myRequests.filter(r => {
    const matchStatus = statusFilter === 'All' || r.status === statusFilter;
    const matchCategory = categoryFilter === 'All' || r.category === categoryFilter;
    const matchSearch = !search || r.title.toLowerCase().includes(search.toLowerCase()) || r.id.toLowerCase().includes(search.toLowerCase());
    return matchStatus && matchCategory && matchSearch;
  });

  return (
    <DashboardLayout navItems={NAV_ITEMS}>
      <div className="page-header">
        <h1 className="page-title">My Requests</h1>
        <p className="page-subtitle">Track the status of all your submitted service requests</p>
      </div>

      {/* Filters */}
      <div className="card filters-bar animate-fade-up">
        <input
          className="search-input"
          type="text"
          placeholder="Search by title or request ID..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
        <div className="filter-group">
          <span className="filter-label">Status:</span>
          <div className="filter-chips">
            {STATUS_FILTERS.map(s => (
              <button
                key={s}
                className={`filter-chip ${statusFilter === s ? 'active' : ''}`}
                onClick={() => setStatusFilter(s)}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
        <div className="filter-group">
          <span className="filter-label">Category:</span>
          <div className="filter-chips">
            {CATEGORY_FILTERS.map(c => (
              <button
                key={c}
                className={`filter-chip ${categoryFilter === c ? 'active' : ''}`}
                onClick={() => setCategoryFilter(c)}
              >
                {c}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="card animate-fade-up" style={{ animationDelay: '0.1s', overflow: 'hidden' }}>
        <div className="table-header-row">
          <span className="table-count">{filtered.length} request{filtered.length !== 1 ? 's' : ''}</span>
          <Link to="/student/submit" className="btn btn-primary btn-sm">+ New Request</Link>
        </div>

        {filtered.length === 0 ? (
          <div className="empty-state">
            <div className="icon">🔍</div>
            <h3>No requests found</h3>
            <p>
              {myRequests.length === 0
                ? 'You haven\'t submitted any requests yet.'
                : 'Try adjusting your search or filter criteria.'}
            </p>
            {myRequests.length === 0 && (
              <Link to="/student/submit" className="btn btn-primary" style={{ marginTop: 16 }}>
                Submit your first request
              </Link>
            )}
          </div>
        ) : (
          <div className="table-scroll">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Request ID</th>
                  <th>Category</th>
                  <th>Title</th>
                  <th>Status</th>
                  <th>Submitted</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map(r => (
                  <tr key={r.id}>
                    <td><span className="req-id-cell">{r.id}</span></td>
                    <td><span className="category-chip">{r.category}</span></td>
                    <td>
                      <div className="req-title">{r.title}</div>
                      <div className="req-desc-preview">{r.description.slice(0, 60)}...</div>
                    </td>
                    <td><StatusBadge status={r.status} /></td>
                    <td className="date-cell">{new Date(r.createdAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}
